<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Crypt};use App\Services\Marketing\MarketingAttribution;
class MarketingTrackingController extends Controller {
 public function redirect(Request $r,MarketingAttribution $s,string $link){$l=$s->link($link);abort_unless($l,404);$u=parse_url($l->destination_url);abort_unless(in_array($u['scheme']??'',['http','https'],true)&&!isset($u['user'])&&!isset($u['pass'])&&strtolower($u['host']??'')===strtolower((string)parse_url(config('app.url'),PHP_URL_HOST)),404);$url=$l->destination_url;if($s->enabled()){DB::table('marketing_analytics_events')->insert(['merchant_key'=>$l->merchant_key,'campaign_id'=>$l->campaign_id,'link_id'=>$l->id,'kind'=>'request','dedupe_key'=>'request:'.\Illuminate\Support\Str::uuid(),'occurred_at'=>now()]);$hash='';if(str_contains($url,'#'))[$url,$hash]=explode('#',$url,2);$url.=(str_contains($url,'?')?'&':'?').'jw_ref='.rawurlencode(Crypt::encryptString(json_encode(['id'=>$l->id,'at'=>now()->timestamp])));if($hash!=='')$url.='#'.$hash;}return redirect()->away($url)->header('Cache-Control','no-store')->header('Referrer-Policy','same-origin');}
 public function consent(Request $r,MarketingAttribution $s){$d=$r->validate(['accepted'=>'required|boolean','token'=>'nullable|string|max:4000']);$r->session()->put('marketing.consent',$d['accepted']);if(!$d['accepted'])$r->session()->forget(['marketing.sid','marketing.activity','marketing.first','marketing.last','marketing.checkout','marketing.checkout_touch']);elseif($d['token']??null){try{$tracked=$s->arrival($r,$d['token']);}catch(\Throwable){return response()->json(['accepted'=>true,'tracked'=>false]);}}return response()->json(['accepted'=>$d['accepted']]);}
 public function arrival(Request $r,MarketingAttribution $s){$d=$r->validate(['token'=>'required|string|max:4000']);try{$tracked=$s->arrival($r,$d['token']);}catch(\Throwable){return response()->json(['tracked'=>false]);}return response()->json(['tracked'=>$tracked]);}
 public function page(Request $r,MarketingAttribution $s){$d=$r->validate(['navigation_id'=>'required|uuid','item_id'=>'nullable|integer']);try{$tracked=$s->websiteEvent($r,'page_view',$d['navigation_id']);if(!empty($d['item_id'])&&\App\Models\Product::whereKey($d['item_id'])->where('status','active')->exists())$s->websiteEvent($r,'view_item',$d['navigation_id'].':'.$d['item_id'],['product_id'=>$d['item_id']]);return response()->json(['tracked'=>$tracked]);}catch(\Throwable){return response()->json(['tracked'=>false]);}}
}
